/// 用 fixture 脚本建临时世界，返回世界目录。
/// fixture 脚本经 NOVEL_BIN 调 novel；脚本路径从 CARGO_MANIFEST_DIR 解析到仓库根。
fn setup_fixture(fixture: &str) -> tempfile::TempDir {
    let dir = tempdir().unwrap();
    let novel_bin = assert_cmd::cargo::cargo_bin("novel");
    // CARGO_MANIFEST_DIR = crates/novel-cli，仓库根 = 其上两级。
    let manifest = env!("CARGO_MANIFEST_DIR");
    let repo_root = std::path::Path::new(manifest)
        .parent().and_then(|p| p.parent())
        .expect("无法从 CARGO_MANIFEST_DIR 解析仓库根");
    let script = repo_root.join(format!("contracts/cli/fixtures/{fixture}.sh"));
    let status = std::process::Command::new("bash")
        .arg(&script)
        .arg(dir.path())
        .env("NOVEL_BIN", &novel_bin)
        .status()
        .expect("fixture 脚本启动失败");
    assert!(status.success(), "fixture {fixture} 执行失败: {status}\n  script: {}", script.display());
    dir
}

